-- WorldProject: interne Betriebsfinanzierung und Expansionskredite
create table if not exists public.business_internal_transfers (id bigserial primary key,user_id bigint not null references public.users(id) on delete cascade,from_company_id bigint not null references public.companies(id) on delete cascade,to_company_id bigint not null references public.companies(id) on delete cascade,amount numeric(18,2) not null check(amount>0),created_at timestamptz not null default now());
create table if not exists public.business_expansion_loans (id bigserial primary key,user_id bigint not null references public.users(id) on delete cascade,company_id bigint not null references public.companies(id) on delete cascade,principal numeric(18,2) not null check(principal>0),annual_rate numeric(8,6) not null check(annual_rate>=0),term_months integer not null check(term_months>0),remaining_principal numeric(18,2) not null check(remaining_principal>=0),monthly_payment numeric(18,2) not null check(monthly_payment>0),status text not null default 'active',created_at timestamptz not null default now());
alter table public.business_internal_transfers enable row level security;alter table public.business_expansion_loans enable row level security;
create policy "own transfer history read" on public.business_internal_transfers for select to authenticated using(user_id=(select id from public.users where auth_user_id=auth.uid()));
create policy "own expansion loans read" on public.business_expansion_loans for select to authenticated using(user_id=(select id from public.users where auth_user_id=auth.uid()));
-- Die produktiven RPCs werden in Supabase als atomare security-definer Funktionen installiert.
